import{z as l,x as i,o as E,c as d,q as o,j as B,D as a,d as t,s as n,S,b as s}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"SSE 与服务器推送","description":"","frontmatter":{"title":"SSE 与服务器推送","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sse-server-push.md","filePath":"cs/sse-server-push.md","lastUpdated":1791413859000}'),A={name:"cs/sse-server-push.md"};function p(c,e,T,h,C,D){const r=i("Mermaid");return E(),d("div",null,[e[2]||(e[2]=o('<h1 id="sse-与服务器推送" tabindex="-1">SSE 与服务器推送 <a class="header-anchor" href="#sse-与服务器推送" aria-label="Permalink to &quot;SSE 与服务器推送&quot;">​</a></h1><div class="epigraph"><p>SSE 用一条永不结束的 HTTP 响应流文本事件；HTTP/2 服务器推送则预推缓存资源，对象不同，都常被误叫「推送」。</p><footer>—— 据 W3C Server-Sent Events；RFC 9113 服务器推送整理</footer></div><p><a href="/cs/websocket">WebSocket</a> 是双向帧。<a href="/cs/websocket">上一课</a> 对只读更新偏重。缺口是 <strong>SSE</strong> 与 <strong>H2 PUSH</strong> 对照：一个是事件流，一个是推资源。本课不把 gRPC 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>股票 ticker、通知：服务器 → 客户端即可。SSE：<code>text/event-stream</code>，chunked 或 H2 流上发 <code>data:</code> 行，浏览器自动重连并带 <code>Last-Event-ID</code>。仍是 HTTP 语义，过代理比 WS 容易。H2/H3 的 PUSH：服务器猜测下一资源推进缓存，实现与隐私问题导致浏览器削弱——不是 SSE 替代。</p><p><span class="marginnote"><code>Last-Event-ID</code> 翻译一下：就是断线重连时浏览器自动带的「进度条」——「我上次读到编号 1024 的事件」。服务器据此判断该补发 1025 之后的内容还是重放全量，不用客户端自己造断点续传协议。这也是 SSE 比裸 HTTP 长轮询好用的核心细节之一。</span></p><p>不要把 SSE 写成 WebSocket 的子集协议。</p><p><span class="marginnote">WHATWG/W3C SSE。H3 不用 H2 那种 PUSH，点名。本课不写 EventSource API 全集。</span></p><h3 id="单向事件流" tabindex="-1">单向事件流 <a class="header-anchor" href="#单向事件流" aria-label="Permalink to &quot;单向事件流&quot;">​</a></h3><p>持久 GET，自动重连带 Last-Event-ID。H2 PUSH 是资源预推，对象不同。代理缓冲会把实时变成批量。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：轮询 / SSE / WS / H2 PUSH。画：GET 事件流 → 多 event 块。与 Cookie：同一请求会话。压缩：对事件流要小心缓冲延迟。</p>',12)),(E(),B(S,null,{default:a(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20GET%5B%22GET%20event-stream%22%5D%20--%3E%20EV%5B%22data%20%E8%A1%8C%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20EV%20--%3E%20REC%5B%22Last-Event-ID%20%E9%87%8D%E8%BF%9E%22%5D%0A%20%20PUSH%5B%22H2%20PUSH%22%5D%20--%3E%20CACHE%5B%22%E5%A1%AB%E6%B5%8F%E8%A7%88%E5%99%A8%E7%BC%93%E5%AD%98%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s("h2",{id:"机制",tabindex:"-1"},[t("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=s("p",null,"反向代理要关缓冲，否则 SSE 变成批量。负载均衡空闲超时会拆流，要心跳注释行。HOL：H1 上 SSE 占一条持久连接。无线：重连风暴。与 QUIC 多流：可用专用流跑 SSE 风格。",-1)),(E(),B(S,null,{default:a(()=>[n(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRV%5B%22SSE%20%E6%9C%8D%E5%8A%A1%E5%99%A8%E6%8C%81%E7%BB%AD%E5%86%99%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20PROXY%5B%22%E5%8F%8D%E5%90%91%E4%BB%A3%E7%90%86%EF%BC%9A%E5%93%8D%E5%BA%94%E7%BC%93%E5%86%B2%E6%9C%AA%E5%85%B3%22%5D%0A%20%20PROXY%20--%3E%20BATCH%5B%22%E4%BA%8B%E4%BB%B6%E6%94%92%E6%88%90%E4%B8%80%E6%89%B9%E6%89%8D%E8%BD%AC%E5%8F%91%EF%BC%8C%E5%AE%9E%E6%97%B6%E5%8F%98%E6%89%B9%E5%A4%84%E7%90%86%22%5D%0A%20%20SRV%20--%3E%20LB%5B%22%E8%B4%9F%E8%BD%BD%E5%9D%87%E8%A1%A1%EF%BC%9A%E8%BF%9E%E6%8E%A5%E7%A9%BA%E9%97%B2%E8%AE%A1%E6%97%B6%22%5D%0A%20%20LB%20--%3E%20CUT%5B%22%E9%9D%99%E9%BB%98%E6%9C%9F%E4%B8%80%E5%88%B0%E8%BF%9E%E6%8E%A5%E8%A2%AB%E6%8B%86%22%5D%0A%20%20HB%5B%22%E5%BF%83%E8%B7%B3%E6%B3%A8%E9%87%8A%E8%A1%8C%EF%BC%9A%3A%20ping%22%5D%20--%3E%20LB%0A%20%20CUT%20--%3E%20STORM%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E9%9B%86%E4%BD%93%E9%87%8D%E8%BF%9E%EF%BC%8C%E5%BD%A2%E6%88%90%E9%A3%8E%E6%9A%B4%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=o('<p><span class="marginnote">心跳注释行像开会时定期说一句「我还在」——以 <code>:</code> 开头的行对客户端是透明的，不产生事件，但让中间设备的「空闲计时器」一直被刷新，流就不会被当成死连接拆掉。漏了这一步，SSE 在生产环境最常见的症状就是「每几分钟莫名其妙断一次」。</span></p><p>H2 PUSH 与 CDN 预取后课相关，不是实时消息。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MQTT 的全部。REST 与 gRPC 是下一课。后课默认：SSE 是单向 HTTP 事件流；PUSH 是资源预推。</p><p>把所有实时都升级到 WS 会浪费。</p><p>下一课<a href="/cs/rest-grpc">REST 与 gRPC</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SSE：持久 GET，文本事件，易过 HTTP 中间件。</li><li>H2 PUSH：资源，不是消息总线。</li><li>代理缓冲与超时是部署坑。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：W3C SSE；RFC 9113。</li></ul>',8))])}const H=l(A,[["render",p]]);export{m as __pageData,H as default};
